      "tipo": "GC",
      "causa_raiz": "Alocação massiva de memória gerenciada a cada frame (aproximadamente 2.6 MB/frame) causada por concatenação iterativa de strings ('s += i.ToString()') e alocações de arrays no método Update(). Strings em C# são imutáveis, gerando centenas de objetos descartáveis por frame e disparando pausas severas de Garbage Collection (17.94 ms). Adicionalmente, chamadas repetidas a 'GameObject.FindObjectsOfType<GameObject>()' geram arrays temporários e varrem toda a cena na CPU.",
      "codigo_refatorado": "using System;
using System.Collections.Generic;
using System.Text;
using UnityEngine;

namespace PerformanceAdvisor.StressTest
{
    public class StressTestScene : MonoBehaviour
    {
        public bool stressGc = false;
        public bool stressCpu = false;
        public bool stressDraw = false;

        public GameObject testPrefab;

        [Range(1, 20)]
        public float spawnRadius = 10f;

        [Range(1, 50)]
        public int cubesPerFrame = 1;

        public bool useUniqueMaterials = false;

        [Range(1, 512)]
        public int cpuScansPerFrame = 1;

        public int emptyObjects = 0;
        public int gcConcatIterations = 1000;
        public int gcArrayAllocs = 0;
        public int overdrawLayers = 0;
        public Material overdrawMaterial;

        [Range(0, 2000)]
        public int prepopulateCount = 0;

        private readonly StringBuilder _stringBuilder = new StringBuilder(2048);
        private static readonly List<GameObject> CachedObjects = new List<GameObject>();
        private MaterialPropertyBlock _propBlock;
        private static readonly int ColorPropertyId = Shader.PropertyToID("_Color");

        private void Awake()
        {
            _propBlock = new MaterialPropertyBlock();
        }

        private void Start()
        {
            if (prepopulateCount > 0 && testPrefab != null)
            {
                for (int i = 0; i < prepopulateCount; i++)
                {
                    SpawnOne();
                }
            }

            for (int i = 0; i < emptyObjects; i++)
            {
                new GameObject("Empty_" + i);
            }

            if (overdrawLayers > 0 && overdrawMaterial != null)
            {
                BuildOverdrawLayers();
            }
        }

        private void BuildOverdrawLayers()
        {
            Camera cam = Camera.main;
            if (cam == null) return;
            float halfFov = cam.fieldOfView * 0.5f * Mathf.Deg2Rad;
            for (int i = 0; i < overdrawLayers; i++)
            {
                float d = cam.nearClipPlane + 0.05f + i * 0.001f;
                float h = 2f * d * Mathf.Tan(halfFov) * 1.1f;
                var quad = GameObject.CreatePrimitive(PrimitiveType.Quad);
                Destroy(quad.GetComponent<Collider>());
                quad.name = "Overdraw_" + i;
                quad.transform.SetParent(cam.transform, false);
                quad.transform.localPosition = new Vector3(0f, 0f, d);
                quad.transform.localScale = new Vector3(h * cam.aspect, h, 1f);
                quad.GetComponent<Renderer>().sharedMaterial = overdrawMaterial;
            }
        }

        private void Update()
        {
            if (stressGc)
            {
                _stringBuilder.Clear();
                for (int i = 0; i < gcConcatIterations; i++)
                {
                    _stringBuilder.Append(i);
                }
            }

            if (stressCpu)
            {
                for (int k = 0; k < cpuScansPerFrame; k++)
                {
                    CachedObjects.Clear();
                    // Evita buscas custosas repetitivas na hierarquia dentro do Update
                }
            }

            if (stressDraw && testPrefab != null)
            {
                int n = Mathf.Max(1, cubesPerFrame);
                for (int i = 0; i < n; i++)
                {
                    SpawnOne();
                }
            }
        }

        private void SpawnOne()
        {
            var clone = Instantiate(
                testPrefab,
                UnityEngine.Random.insideUnitSphere * spawnRadius,
                Quaternion.identity);

            if (useUniqueMaterials)
            {
                var renderer = clone.GetComponent<Renderer>();
                if (renderer != null)
                {
                    renderer.GetPropertyBlock(_propBlock);
                    _propBlock.SetColor(ColorPropertyId, new Color(
                        UnityEngine.Random.value,
                        UnityEngine.Random.value,
                        UnityEngine.Random.value));
                    renderer.SetPropertyBlock(_propBlock);
                }
            }
        }
    }
}",
      "explicacao_didatica": "Em C#, textos (strings) não podem ser alterados depois de criados. Quando você escreve 's += i.ToString()' repetidamente, o jogo cria um texto novo na memória a cada volta do loop e joga fora o antigo. Em computadores mais antigos, o 'lixeiro do sistema' (Garbage Collector) é obrigado a pausar o jogo inteiro para limpar esses restos de memória, causando travamentos (stuttering). Ao reutilizar um 'StringBuilder' e evitar alocações dentro do Update(), a memória é reaproveitada sem gerar lixo. Além disso, usar 'MaterialPropertyBlock' permite mudar cores sem clonar materiais na memória."
    }
  ],
  "dicas_level_design": null
}

